contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We accept two parameters: the guess hash to lock, and the number of empty blocks to advance
    // (simulated by calling an unrelated view to consume transactions isn't possible here), so instead
    // we rely on the caller to choose a block number such that block.number > lock block when calling settle.
    // To observe effects, we send exactly 1 ether to lockInGuess and then call settle in the same transaction.
    // Because C sets lock block to block.number + 1, calling settle immediately will revert due to block.number not greater.
    // Therefore the test will perform: lockInGuess (should succeed), then we assert on immediate observable invariant:
    // after lockInGuess, the stored guess.block != 0 and guess.guess equals the provided hash, and contract balance increased by 1 ether.
    // This is a general rule about lockInGuess behavior for any hash and provided exact 1 ether.

    function run(bytes32 hash) public payable {
        require(msg.value == 1 ether);
        // Ensure this contract holds the ether to forward
        // We will call lockInGuess with exactly 1 ether
        uint256 balBefore = address(c).balance;

        // call lockInGuess; must be top-level statement that changes c
        c.lockInGuess{value: 1 ether}(hash);

        // Read the stored Guess via the autogenerated getter: guesses(address) is public so getter exists.
        (uint256 storedBlock, bytes32 storedGuess) = c.guesses(address(this));

        uint256 balAfter = address(c).balance;

        // General rule asserted:
        // - lockInGuess must have set a non-zero block number for this caller (block number of lock) and stored the provided hash
        // - contract balance must have increased by exactly 1 ether as a result of successful lockInGuess
        assert(storedBlock != 0 && storedGuess == hash && balAfter == balBefore + 1 ether);
    }

    receive() external payable {}
}

