contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot access the internal mapping directly, so we use the contract's behavior:
    // After calling lockInGuess with 1 ether, the contract requires that this caller's stored block was 0 before the call
    // (otherwise lockInGuess reverts). We check that the call succeeds, that c's balance increased by 1 ether,
    // and that a subsequent immediate call to settle() reverts because settle requires block.number > stored.block
    // (since lockInGuess sets stored.block = block.number + 1). From these observations we infer that stored.block was set to a nonzero value and stored.guess equals the supplied hash (because lockInGuess would have reverted if there was an active guess).

    // single public function driven by inputs
    function run(bytes32 hash) public payable {
        // this contract must forward exactly 1 ether to lockInGuess
        require(msg.value == 1 ether);
        // ensure this contract has the ether to forward
        require(address(this).balance >= 1 ether);

        uint256 balBefore = address(c).balance;

        // call lockInGuess forwarding exactly 1 ether; it will revert if this contract already had an active guess
        bool lockReverted = false;
        try c.lockInGuess{value: 1 ether}(hash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        uint256 balAfter = address(c).balance;

        // Now try calling settle(); according to the contract logic, immediately after lockInGuess
        // settle() should revert because block.number is NOT greater than stored.block (stored.block == current+1).
        bool settleReverted = false;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // General rule asserted:
        // If lockInGuess did not revert (meaning there was no prior active guess and exactly 1 ether was sent),
        // then c's balance must have increased by exactly 1 ether, and an immediate call to settle() must revert
        // (because stored.block was set to block.number+1, so block.number > stored.block is false).
        assert((!lockReverted && balAfter == balBefore + 1 ether && settleReverted) || lockReverted);
    }

    // receive to accept ether so this contract can forward funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single property-based test function.
    // Inputs: a bytes32 guess hash and an amount to forward (must be 1 ether to succeed).
    function run(bytes32 hash, uint256 amount) public payable {
        // ensure this test contract has enough balance to forward
        require(address(this).balance >= amount);

        uint256 balBefore = address(c).balance;

        bool lockReverted;
        // call lockInGuess forwarding `amount` (will succeed only if amount == 1 ether and no active guess)
        try c.lockInGuess{value: amount}(hash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        uint256 balAfter = address(c).balance;

        // Try settling immediately; if lock succeeded settle should revert because stored.block was set to block.number+1
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // General invariant:
        // - If lockInGuess succeeded, c's balance increased by exactly amount (which should be 1 ether for success)
        //   and an immediate settle() call must revert (stored.block == block.number+1 => block.number > stored.block is false).
        // - If lockInGuess reverted, we make no claim about balance change except it must equal balBefore (since call reverted,
        //   no state change should have occurred in c). So either lock reverted and balance unchanged, or lock succeeded and
        //   balance increased by amount and immediate settle reverted.
        assert(
            (lockReverted && balAfter == balBefore) ||
            (!lockReverted && balAfter == balBefore + amount && settleReverted)
        );
    }

    // allow this test contract to receive ether so it can forward funds
    receive() external payable {}
}

