contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // hash - value to lock in
    // sendLock - amount to send to lockInGuess (should be 1 ether to succeed)
    // advanceBlocks - a number of dummy no-ops to let block.number increase logically (not actually usable here,
    //                  but kept as a parameter for generality; we will not depend on real block progression).
    function run(bytes32 hash, uint sendLock, uint advanceBlocks) public payable {
        require(address(this).balance >= sendLock + 2 ether); // ensure we can fund lock and potential payout
        // Ensure fresh state: for a fresh deployment of c, there is no prior guess for this caller.

        // record balances before any interactions
        uint beforeC = address(c).balance;

        bool lockedReverted;
        // attempt to lock a guess by sending exactly sendLock wei
        try c.lockInGuess{value: sendLock}(hash) {
            lockedReverted = false;
        } catch {
            lockedReverted = true;
        }

        // read the recorded block for this caller via the public getter; guesses is public so compiler generates a getter
        (uint recordedBlock, bytes32 recordedGuess) = c.guesses(address(this));

        // Optionally attempt to call settle(); it may revert depending on recordedBlock and block.number
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint afterC = address(c).balance;
        (uint recordedBlockAfter, bytes32 recordedGuessAfter) = c.guesses(address(this));

        // General rule:
        // - If settle succeeded (did not revert) then the contract must have paid out 2 ether (balance decreased by 2 ether)
        //   and the stored block for this caller must be cleared (be 0).
        // - If settle reverted then neither the contract balance nor the stored block should have changed as a result
        //   of the settle call (i.e., recordedBlockAfter == recordedBlock and afterC == afterCBeforeSettle).
        // Note: If lockInGuess reverted, settle cannot succeed (no guess stored); the rule still applies because
        // settleReverted will be true and we assert the unchanged conditions.

        // compute the contract balance just before settle: if settle was attempted, before-settle balance equals
        // the balance recorded right after lock attempt; else it's the same as afterC as well. To capture before-settle
        // we reuse beforeC and take into account lock success.
        uint afterLockBal = beforeC + (lockedReverted ? 0 : sendLock);

        // If settle succeeded: afterC should be afterLockBal - 2 ether, and stored block cleared.
        // If settle reverted: afterC should equal afterLockBal and stored block unchanged by settle.
        assert(
            !settleReverted
                ? (afterC == afterLockBal - 2 ether && recordedBlockAfter == 0)
                : (afterC == afterLockBal && recordedBlockAfter == recordedBlock)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // hash - value to lock in
    // sendLock - amount to send to lockInGuess (should be 1 ether to succeed)
    function run(bytes32 hash, uint sendLock) public payable {
        // We need funds to potentially send lock and to receive potential payout forwarding; require enough balance.
        require(address(this).balance >= sendLock + 2 ether);

        // Record contract balance before any interaction
        uint beforeC = address(c).balance;

        // Attempt lockInGuess and record whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: sendLock}(hash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Balance immediately after attempting lock
        uint afterLock = address(c).balance;

        // Read the stored Guess for this caller via the autogenerated public getter: guesses(address) returns (uint, bytes32)
        (uint recordedBlockBeforeSettle, bytes32 recordedGuessBeforeSettle) = c.guesses(address(this));

        // Attempt to call settle and record whether it reverted
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Balance after settle attempt
        uint afterSettle = address(c).balance;

        // Read stored Guess after settle
        (uint recordedBlockAfterSettle, bytes32 recordedGuessAfterSettle) = c.guesses(address(this));

        // The general invariant to prove:
        // If settle succeeded then recorded block must have been cleared (now 0) and the contract balance
        // decreased by exactly 2 ether relative to the balance just after the lock attempt.
        // If settle reverted then both the recorded block and contract balance must be unchanged by the settle call.
        assert(
            !settleReverted
                ? (recordedBlockAfterSettle == 0 && afterSettle + 2 ether == afterLock)
                : (recordedBlockAfterSettle == recordedBlockBeforeSettle && afterSettle == afterLock)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take parameters to drive lockInGuess and settle timing.
    // amountLock must be 1 ether to satisfy C.lockInGuess; we require this externally.
    // targetHash is arbitrary bytes32 to pass as guess.
    function run(uint amountLock, bytes32 targetHash) public payable {
        require(amountLock == 1 ether);
        // Ensure this test contract has enough balance to send the lock amount
        require(address(this).balance >= amountLock);

        // Record c's balance before any action
        uint before = address(c).balance;

        // Call lockInGuess with 1 ether. This must succeed (or revert) depending on C's state.
        bool lockedReverted;
        try c.lockInGuess{value: amountLock}(targetHash) {
            lockedReverted = false;
        } catch {
            lockedReverted = true;
        }

        // After attempting lock, read c balance
        uint afterLock = address(c).balance;

        // We may or may not have succeeded in locking. If we succeeded, C.guesses(this).block should be nonzero
        // but guesses mapping and struct are not public; however C.guesses is declared public in contract C,
        // so an auto-generated getter exists taking address and returning (uint, bytes32).
        (uint guessBlock, bytes32 storedGuess) = c.guesses(address(this));

        // Try to call settle. It may revert depending on block numbers and prior state.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // After settle attempt, read c balance again
        uint afterSettle = address(c).balance;

        // We assert a general financial invariant: c's balance never increases as a result
        // of these interactions from the perspective of this transaction (no calls that send
        // Ether into c were made except lockInGuess which we already accounted for). Also,
        // settle cannot pay out more than 2 ether in a single call to the caller, so the
        // contract's balance cannot decrease by more than 2 ether in the settle step.
        // We express this as: afterSettle <= before and (before - afterSettle) <= 2 ether.
        // Additionally, if lockInGuess succeeded, guessBlock should be non-zero; if it reverted,
        // guessBlock should be zero.

        assert(
            // c.balance did not increase overall
            afterSettle <= before
            // and c paid out at most 2 ether total
            && (before - afterSettle) <= 2 ether
            // consistency between lock revert flag and stored guessBlock
            && (lockedReverted ? guessBlock == 0 : guessBlock != 0)
        );
    }

    receive() external payable {}
}

