contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Parameters:
    // amountLock: must be 1 ether to match C.lockInGuess requirement
    // guess: arbitrary bytes32 to pass to lockInGuess
    // We make this function payable so the fuzzer can fund this contract; we require it has enough balance.
    function run(uint amountLock, bytes32 guess) public payable {
        require(amountLock == 1 ether);
        require(address(this).balance >= amountLock);

        // Record C balance before any interaction
        uint beforeBalance = address(c).balance;

        // Try to call lockInGuess with 1 ether and record whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: amountLock}(guess) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Read c's balance after the lock attempt
        uint afterLockBalance = address(c).balance;

        // Read the public getter for guesses(msg.sender).block via the auto-generated getter.
        // The struct is stored under mapping(address => Guess) guesses; the getter is guesses(address) returning (uint, bytes32).
        (uint lockedBlock, bytes32 storedGuess) = c.guesses(address(this));

        // Now attempt to call settle and observe whether it reverts
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Read C balance after settle attempt and the mapping entry again
        uint afterSettleBalance = address(c).balance;
        (uint lockedBlockAfter, bytes32 storedGuessAfter) = c.guesses(address(this));

        // General rule (single assert):
        // - If lockInGuess reverted, C's balance did not increase due to that call (afterLockBalance == beforeBalance),
        // - If lockInGuess succeeded then lockedBlock != 0 (we have a reservation), and afterLockBalance >= beforeBalance,
        // - If settle succeeded then the mapping entry for this address must have been cleared (lockedBlockAfter == 0),
        //   and C's balance did not increase as a result of settle (afterSettleBalance <= afterLockBalance).
        assert(
            (
                lockReverted
                ? (afterLockBalance == beforeBalance)
                : (lockedBlock != 0 && afterLockBalance >= beforeBalance)
            )
            && (
                settleReverted
                ? true
                : (lockedBlockAfter == 0 && afterSettleBalance <= afterLockBalance)
            )
        );
    }

    receive() external payable {}
}
